// src/MapComponent.js
import React, { useEffect, useRef } from 'react';
import mapboxgl from 'mapbox-gl';
import 'mapbox-gl/dist/mapbox-gl.css'; 
import { dumplingLocations, glowInTheDarkThings } from './data';
import gyozaIcon from './assets/gyoza.png';

const MapComponent = () => {
  const mapContainer = useRef(null); // This will reference the map container

  useEffect(() => {
    mapboxgl.accessToken = 'pk.eyJ1IjoidGxhYyIsImEiOiJjamYwY3N6MnYwbG4yMzNvaDlsdzY0NW03In0.cthaFUf4255KncCJn1FmRw'; // Replace with your Mapbox access token

    // Initialize the map
    const map = new mapboxgl.Map({
      container: mapContainer.current, // The div where the map will be rendered
      style: 'mapbox://styles/mapbox/streets-v11', // Map style
      center: [-79.3832, 43.6532], // Coordinates for Toronto, Ontario (Longitude, Latitude)
      zoom: 12, // Initial zoom level
    });



    // Loop through the markers data and add each marker to the map

    dumplingLocations.forEach((markerData) => {
      const { name, longitude, latitude } = markerData;
      
      // Create a custom marker element
      const el = document.createElement('div');
      el.className = 'custom-marker';
      el.style.backgroundImage = 'url(${gyozaIcon})';
      el.style.width = '32px';
      el.style.height = '32px';
      el.style.cursor = 'pointer';

      // Create the marker and add it to the map

      // Create and add marker for each location in the markers array
      new mapboxgl.Marker({ element: el})
        .setLngLat([longitude, latitude])
        .setPopup(new mapboxgl.Popup().setHTML(`<h3>${name}</h3>`)) // Optional: Add a popup with the name of the location
        .addTo(map);
    });

    // Loop through the markers data and add each marker to the map
    glowInTheDarkThings.forEach((markerData) => {
      const { name, longitude, latitude } = markerData;

      // Create and add marker for each location in the markers array
      new mapboxgl.Marker()
        .setLngLat([longitude, latitude])
        .setPopup(new mapboxgl.Popup().setHTML(`<h3>${name}</h3>`)) // Optional: Add a popup with the name of the location
        .addTo(map);
    });



    // Cleanup the map instance when the component is unmounted
    return () => map.remove();
  }, []);

  return <div ref={mapContainer} style={{ height: '800px', width: '100%' }} />;
};

export default MapComponent;
